patch:
diff --git a/repro/no-var-tdz.js b/repro/no-var-tdz.js
new file mode 100644
index 0000000..e70762e
--- /dev/null
+++ b/repro/no-var-tdz.js
@@ -0,0 +1,35 @@
+"use strict";
+// Reproduction for "[no-var] Fix causes ReferenceError" (report snippet, verbatim).
+// Usage: node repro/no-var-tdz.js [path-to-eslint-package]   (default: this checkout)
+const path = require("node:path");
+const pkg = process.argv[2] ? path.resolve(process.argv[2]) : path.join(__dirname, "..");
+const { Linter } = require(path.join(pkg, "lib/api"));
+const version = require(path.join(pkg, "package.json")).version;
+
+const code = `export function a() {
+    console.log(o);
+    var o;
+    return o;
+}`;
+const config = [{ rules: { "no-var": ["error"] } }];
+
+const linter = new Linter({ configType: "flat" });
+const messages = linter.verify(code, config, "x.js");
+const { output, fixed } = linter.verifyAndFix(code, config, "x.js");
+
+console.log(`eslint ${version}`);
+for (const m of messages) console.log(`  ${m.line}:${m.column} ${m.message} (${m.ruleId}) fix=${m.fix ? "yes" : "no"}`);
+console.log(`fixed=${fixed}\n--- output ---\n${output}\n--------------`);
+
+// Run the fixed code: ReferenceError means the fix introduced a TDZ error.
+let runtime;
+try {
+    new Function(output.replace(/^export /u, "") + "\na();")();
+    runtime = "ok";
+} catch (e) {
+    runtime = `${e.name}: ${e.message}`;
+}
+console.log(`calling a() on output: ${runtime}`);
+const bug = fixed && /^ReferenceError/u.test(runtime);
+console.log(bug ? "BUG: autofix produced code that throws ReferenceError" : "no bug: autofix did not introduce a ReferenceError");
+process.exitCode = bug ? 1 : 0;
